package com.local.yuanatlas;
import android.graphics.*;
import android.util.Base64;
/** 属性圆标模板取自用户提供的两游戏原图，仅比较圆标内部，排除立绘与旁边标签。 */
final class CaptureAttribute {
 private static final String[] LABELS={"地","火","水","风","阳","阴","地","火","水","风","阳","阴"};
 private static final String[] DATA={"","","","","","","","","","","",""};
 private static final byte[][] TEMPLATES=new byte[DATA.length][];
 static {for(int i=0;i<DATA.length;i++)TEMPLATES[i]=Base64.decode(DATA[i],Base64.DEFAULT);}
 static String icon(Bitmap source,Rect bounds,boolean code){
  float cx=source.getWidth()*.071f,cy=bounds.top+bounds.height()*(code?.304f:.309f),radius=source.getWidth()*.018f;
  Rect box=new Rect(Math.round(cx-radius),Math.round(cy-radius),Math.round(cx+radius),Math.round(cy+radius));
  if(!box.intersect(0,0,source.getWidth(),source.getHeight()))return "";
  Bitmap crop=Bitmap.createBitmap(source,box.left,box.top,box.width(),box.height()),small=Bitmap.createScaledBitmap(crop,16,16,true);
  try{
   double[] scores=new double[6];java.util.Arrays.fill(scores,Double.MAX_VALUE);String[] names={"火","阳","风","水","阴","地"};
   for(int i=0;i<TEMPLATES.length;i++){
    double error=0;int count=0;
    for(int y=0;y<16;y++)for(int x=0;x<16;x++){
     if((x-7.5)*(x-7.5)+(y-7.5)*(y-7.5)>49)continue;
     int c=small.getPixel(x,y),offset=(y*16+x)*3;int[] channels={Color.red(c),Color.green(c),Color.blue(c)};
     for(int k=0;k<3;k++){double delta=(channels[k]-(TEMPLATES[i][offset+k]&255))/255.0;error+=delta*delta;count++;}
    }
    for(int k=0;k<names.length;k++)if(names[k].equals(LABELS[i]))scores[k]=Math.min(scores[k],error/count);
   }
   int best=0;for(int i=1;i<scores.length;i++)if(scores[i]<scores[best])best=i;
   double second=Double.MAX_VALUE;for(int i=0;i<scores.length;i++)if(i!=best)second=Math.min(second,scores[i]);
   // 分数差不足或模板相似度低时留空，绝不单凭立绘颜色判断属性。
   return scores[best]<.028&&second-scores[best]>.009?names[best]:"";
  }finally{if(small!=crop)small.recycle();crop.recycle();}
 }
}
